int main(){setenv("TZ","UTC0",1);tzset();auto now=parseISO("2026-09-09T08:00:00+08:00");assert(now==parseISO("2026-09-09T00:00:00+00:00"));assert(!parseISO(nullptr));assert(!parseISO(""));assert(!parseISO("2026-09-09T08:00:00+88:00"));assert(arrivalAlert(true,true,2,now,now-20,now+300,5));assert(!arrivalAlert(true,true,2,now,now-121,now+300,5));assert(!arrivalAlert(true,true,2,now,now,now+301,5));assert(arrivalAlert(true,true,2,now,now,now+390,5,90));assert(!arrivalAlert(true,true,2,now,now,now+391,5,90));assert(!arrivalAlert(true,true,1,now,now,0,5));assert(!arrivalAlert(true,false,2,now,now,now+60,5));assert(!arrivalAlert(false,true,2,now,now,now+60,5));assert(!arrivalAlert(true,true,2,now,now,now-1,5));assert(!arrivalAlert(true,true,2,now,now+121,now+60,5));assert(displayEtaMinutes(now,0,90)==-1);assert(displayEtaMinutes(now,now+89,90)==0);assert(displayEtaMinutes(now,now+90,90)==0);assert(displayEtaMinutes(now,now+91,90)==1);assert(displayEtaMinutes(now,now+1650,90)==26);assert(displayEtaMinutes(now,now+3457,90)==57);assert(scheduledEtaRemark("Scheduled Bus",""));assert(scheduledEtaRemark("","原定班次"));assert(!scheduledEtaRemark("",""));puts("ETA/time/alert/display lead boundary checks passed");}
